// Package postgres implements the authorization domain's policy store
// against PostgreSQL via jackc/pgx (ADR-0069), and the listener that
// keeps a policy cache current from the writes it announces.
package postgres

import (
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/platform/internal/authz"
	"github.com/garamsh/garam/platform/internal/authz/postgres/db"
)

// Store implements authz.Store against PostgreSQL. The queries are
// generated by sqlc from queries.sql; append-only enforcement on
// policy_versions lives in the schema, not here.
type Store struct {
	pool *pgxpool.Pool
	q    *db.Queries
}

// Compile-time check that Store satisfies authz.Store.
var _ authz.Store = (*Store)(nil)

// New constructs a Postgres-backed policy store.
func New(pool *pgxpool.Pool) *Store {
	return &Store{pool: pool, q: db.New(pool)}
}
